const RANGES=Object.freeze([[1,30],[31,45],[46,60],[61,75],[76,90],[91,105]]);
function clone(x){return x==null?x:JSON.parse(JSON.stringify(x))}
function campaign(g){
 const quest=String(g?.campaign?.currentQuest||'').match(/^Q(\d{3})$/),qn=quest?Number(quest[1]):0;
 if(qn>=1&&qn<=72)return Math.ceil(qn/12);
 const event=String(g?.campaign?.activeEvent||'').match(/^WE(\d{3})$/),en=event?Number(event[1]):0;
 return en>=1&&en<=24?Math.ceil(en/4):null;
}
function cardCampaign(card){const m=String(card?.id||card||'').match(/^EN(\d{3})$/);if(!m)return null;const n=Number(m[1]);return RANGES.findIndex(([a,b])=>n>=a&&n<=b)+1||null}
function allowed(g,card){const c=campaign(g),owner=cardCampaign(card);return !c||!owner||c===owner}
function catalog(g){const c=campaign(g);return CATALOG.filter(x=>!c||cardCampaign(x)===c).map(clone)}
function shuffle(cards,random=Math.random){const out=cards.slice();for(let i=out.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function text(card,severity){return severity<=2?card.a:severity<=4?card.b:severity<=6?card.c:card.d}
function repair(g,options={}){
 const scope=campaign(g);if(!g||!scope)return {changed:false,campaign:scope,removed:[],replaced:[]};
 const pending=options.pendingByHero||{},entries=Object.entries(pending).filter(([,p])=>p&&(p.kind==='encounter'||p.card)&&p.card);
 const local=options.localPending,alias=local?.card?entries.find(([,p])=>p===local||(p.card.id===local.card.id&&Number(p.severity??p.roll)===Number(local.severity??local.roll)&&p.origin?.x===local.origin?.x&&p.origin?.y===local.origin?.y))?.[1]:null;
 if(local?.card&&!alias)entries.push(['local',local]);
 const foreignPending=entries.filter(([,p])=>!allowed(g,p.card)),removed=[];
 for(const field of ['encDeck','encDiscard']){
  if(!Array.isArray(g[field]))continue;
  const keep=g[field].filter(card=>{if(allowed(g,card))return true;removed.push({field,id:card.id});return false});
  if(keep.length!==g[field].length)g[field]=keep;
 }
 if(!removed.length&&!foreignPending.length)return {changed:false,campaign:scope,removed:[],replaced:[]};
 // Keep regional cards and their order in polluted legacy saves. Reconstruct only
 // an all-foreign collection; never refill a legitimately exhausted clean deck.
 if(!(g.encDeck||[]).length&&!(g.encDiscard||[]).length){
  const held=new Map();for(const [,p]of entries.filter(([,p])=>allowed(g,p.card)))held.set(p.card.id,Number(held.get(p.card.id)||0)+1);
  g.encDeck=shuffle(catalog(g).filter(c=>{const n=Number(held.get(c.id)||0);if(!n)return true;held.set(c.id,n-1);return false}),options.random);
 }
 const replaced=[];
 for(const [hero,p]of foreignPending){
  if(!(g.encDeck||[]).length&&(g.encDiscard||[]).length){g.encDeck=shuffle(g.encDiscard,options.random);g.encDiscard=[]}
  const next=g.encDeck?.shift();if(!next)continue;
  const previous=p.card;p.card=clone(next);p.text=text(next,Number(p.severity??p.roll??1));
  p.regionalReplacement33624={previous:previous.id,replacement:next.id,campaign:scope};
  replaced.push({hero,previous:previous.id,replacement:next.id});
 }
 if(alias&&alias!==local&&alias.regionalReplacement33624){local.card=clone(alias.card);local.text=alias.text;local.regionalReplacement33624=clone(alias.regionalReplacement33624)}
 const report={version:VERSION,campaign:scope,removed:[...new Set(removed.map(x=>x.id))],replaced};
 g.encounterDeckRepair33624=clone(report);
 return {changed:true,campaign:scope,removed,replaced,report};
}
return {version:VERSION,ranges:RANGES.map(x=>x.slice()),campaign,cardCampaign,allowed,catalog,repair};
